extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi"):
		return
	var guard := find_by_name(main, "Guard")
	if not check("guard", guard != null, "La guardia deve essere presente"):
		return
	var guard_health := find_by_name(guard, "Health") as Health
	if not check("g_health", guard_health != null, "La guardia deve avere un nodo Health"):
		return

	# Simuliamo il danno da proiettile tramite la sua Hurtbox
	guard_health.take_damage(1)
	check("dmg1", guard_health.current_health == 1, "La guardia deve aver subito 1 danno")
	guard_health.is_invincible = false
	guard_health.take_damage(1)
	await wait_frames(2)
	check("guard_dead", guard.is_queued_for_deletion(), "Con 2 danni la guardia deve chiamare queue_free()")

